<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Domain;

final class ChallengesState
{
    public function __construct(
        public readonly bool $withMfa = false,
        public readonly bool $session = false,
        public readonly ?string $username = null,
        public readonly array $extra = [],
    ) {
    }

    public static function fromLegacy(AuthorizedChalleges $legacy): self
    {
        return new self(
            withMfa: $legacy->mfa,
            session: $legacy->session,
            username: $legacy->username,
            extra: []
        );
    }

    public function toLegacy(): AuthorizedChalleges
    {
        $legacy = new AuthorizedChalleges();
        $legacy->mfa = $this->withMfa;
        $legacy->session = $this->session;
        $legacy->username = $this->username;
        return $legacy;
    }
}
